/// One of an account's own folders, in tree order.
class AccountFolderInfo {
  /// What the server calls it: pass it back to open or move to it.
  final String mailbox;
  final String name;
  final int depth;

  /// False for a folder that only holds other folders.
  final bool selectable;
  final int unread;

  /// How many emails it holds on the server.
  final int total;

  const AccountFolderInfo({
    required this.mailbox,
    required this.name,
    required this.depth,
    required this.selectable,
    required this.unread,
    required this.total,
  });

  @override
  int get hashCode =>
      mailbox.hashCode ^
      name.hashCode ^
      depth.hashCode ^
      selectable.hashCode ^
      unread.hashCode ^
      total.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is AccountFolderInfo &&
          runtimeType == other.runtimeType &&
          mailbox == other.mailbox &&
          name == other.name &&
          depth == other.depth &&
          selectable == other.selectable &&
          unread == other.unread &&
          total == other.total;
}

