      dueIn.hashCode ^
      merchant.hashCode ^
      title.hashCode ^
      time.hashCode ^
      amount.hashCode ^
      currency.hashCode ^
      key.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is VaultReminder &&
          runtimeType == other.runtimeType &&
          dueIn == other.dueIn &&
          merchant == other.merchant &&
          title == other.title &&
          time == other.time &&
          amount == other.amount &&
          currency == other.currency &&
          key == other.key;
}

/// Sent mail nobody has answered yet, and who it waits on.
class WaitingRow {
  final InboxRow row;

  /// The people it went to, by address (not yourself, lists or
  /// machines): who Write again goes to.
  final List<String> to;

  /// "Remind me if nobody replies": when it comes back to the top of
  /// the inbox (Unix seconds), if it still waits then.
  final PlatformInt64? remindAt;

  const WaitingRow({required this.row, required this.to, this.remindAt});

  @override
  int get hashCode => row.hashCode ^ to.hashCode ^ remindAt.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is WaitingRow &&
          runtimeType == other.runtimeType &&
          row == other.row &&
          to == other.to &&
          remindAt == other.remindAt;
}
